/*
 * A267919  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 243" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267919
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   * a(n) = 1 if n + 2 is not a perfect square, * a(n) = 0
 *            otherwise. * * The sequence is obtained by reading the rows of
 *            the * one-dimensional cellular automaton Rule 243 started from a
 *            single ON cell. * This simple closed form matches the triangle
 *            read by rows
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static idx_t isqrt(idx_t n)
{
    idx_t low = 0, high = n, mid = 0, ans = 0;
    while (low <= high)
    {
        mid = low + ((high - low) >> 1);
        if (mid * mid <= n)
        {
            ans = mid;
            low = mid + 1;
        }
        else
        {
            if (mid == 0) break;
            high = mid - 1;
        }
    }
    return ans;
}

seq_t a(idx_t n)
{
    idx_t x = n + (idx_t)2;
    idx_t r = isqrt(x);
    return (seq_t)((r * r == x) ? 0 : 1);
}
